CREATE TABLE IF NOT EXISTS customer_chat_sessions (id VARCHAR(120) PRIMARY KEY, started_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, source VARCHAR(20) NOT NULL CHECK (source IN ('tablet','kiosk','web')), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS customer_chat_messages (id VARCHAR(120) PRIMARY KEY, session_id VARCHAR(120) NOT NULL REFERENCES customer_chat_sessions(id) ON DELETE RESTRICT, role VARCHAR(20) NOT NULL CHECK (role IN ('user','assistant')), content TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_requests (id VARCHAR(120) PRIMARY KEY, session_id VARCHAR(120) NOT NULL REFERENCES customer_chat_sessions(id) ON DELETE RESTRICT, message_id VARCHAR(120) NOT NULL REFERENCES customer_chat_messages(id) ON DELETE RESTRICT, raw_query VARCHAR(500) NOT NULL, normalized_query VARCHAR(500) NOT NULL, matched_product_id VARCHAR(120) REFERENCES products(id) ON DELETE SET NULL, status VARCHAR(20) NOT NULL CHECK (status IN ('available','unavailable','not_found')), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_product_requests_normalized ON product_requests(normalized_query);
CREATE INDEX IF NOT EXISTS idx_product_requests_status ON product_requests(status);
CREATE INDEX IF NOT EXISTS idx_product_requests_created ON product_requests(created_at);
